SEED_NAMES = [
    "火の種",
    "水の種",
    "草の種",
    "岩の種",
    "光の種",
    "闇の種",
]


def add_attribute_growth_seed_drops(
    apps,
    schema_editor,
):

    Item = apps.get_model(
        "inventory",
        "Item",
    )

    FloorDropItem = apps.get_model(
        "battle",
        "FloorDropItem",
    )

    seeds = Item.objects.filter(
        name__in=SEED_NAMES,
    )

    # 1～12層すべてに登録
    for floor in range(1, 13):

        for seed in seeds:

            FloorDropItem.objects.update_or_create(
                floor=floor,
                item=seed,
                defaults={
                    "drop_weight": 100,
                },
            )


def remove_attribute_growth_seed_drops(
    apps,
    schema_editor,
):

    Item = apps.get_model(
        "inventory",
        "Item",
    )

    FloorDropItem = apps.get_model(
        "battle",
        "FloorDropItem",
    )

    seed_ids = Item.objects.filter(
        name__in=SEED_NAMES,
    ).values_list(
        "id",
        flat=True,
    )

    FloorDropItem.objects.filter(
        floor__gte=1,
        floor__lte=12,
        item_id__in=seed_ids,
    ).delete()


